<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\StorePurchaseOrderRequest; use App\Models\{Product,PurchaseOrder,PurchaseRequisition,Supplier,Warehouse}; use App\Services\PurchaseManagementService; use Illuminate\Http\{RedirectResponse,Request}; use Inertia\{Inertia,Response};
class PurchaseOrderController extends Controller { public function __construct(protected PurchaseManagementService $service){} public function index():Response{return Inertia::render('Admin/PurchaseOrders/Index',['orders'=>PurchaseOrder::with('supplier:id,name','warehouse:id,name')->withCount('goodsReceipts')->latest()->paginate(15)]);} public function create():Response{return Inertia::render('Admin/PurchaseOrders/Create',['suppliers'=>Supplier::where('status',true)->orderBy('name')->get(['id','name']),'warehouses'=>Warehouse::orderBy('name')->get(['id','name']),'products'=>Product::where('status',true)->orderBy('name')->get(['id','name','sku','purchase_price']),'requisitions'=>PurchaseRequisition::where('status','approved')->latest()->get(['id','requisition_number']),'suggestedNumber'=>'PO-'.now()->format('Ymd-His')]);} public function store(StorePurchaseOrderRequest $r):RedirectResponse{$po=$this->service->createOrder($r->validated(),$r->user()->id);return redirect()->route('admin.purchase-orders.show',$po)->with('success','Purchase order created.');} public function show(PurchaseOrder $purchaseOrder):Response{return Inertia::render('Admin/PurchaseOrders/Show',['order'=>$purchaseOrder->load('supplier','warehouse','requisition','creator:id,name','approver:id,name','items.product','goodsReceipts')]);} public function approve(Request $r,PurchaseOrder $purchaseOrder):RedirectResponse{$r->user()->can('purchase-orders.approve')||abort(403);$this->service->approveOrder($purchaseOrder,$r->user()->id);return back()->with('success','Purchase order approved.');}}
